// Round-robin pick using the pointer just advanced in Postgres. Routing table
// inlined -- same tradeoff as Resolve Routing Pool above.
const rt = {
  pools: {
    enterprise: [
      { rep_id: 'rep_ana', name: 'Ana Costa', hubspot_owner_id: '' },
      { rep_id: 'rep_bruno', name: 'Bruno Lima', hubspot_owner_id: '' },
    ],
    smb: [
      { rep_id: 'rep_carla', name: 'Carla Nunes', hubspot_owner_id: '' },
      { rep_id: 'rep_diego', name: 'Diego Souza', hubspot_owner_id: '' },
    ],
  },
  routing: [
    { match: { company_size_gte: 200 }, pool: 'enterprise' },
    { match: { company_size_gte: 0 }, pool: 'smb' },
  ],
};
const pool_key = $('Resolve Routing Pool').item.json.pool_key;
const lastIndex = Number($json.last_index) || 0;
const pool = (rt.pools && rt.pools[pool_key]) || [];
const owner = pool.length ? pool[lastIndex % pool.length] : {};
const account_id = $('Upsert Account').item.json.id;
return { json: {
  owner_id: owner.rep_id || null,
  hubspot_owner_id: owner.hubspot_owner_id || '',
  account_id,
} };

// Convergence normalizer: both the reuse branch and the round-robin branch arrive
// here with { owner_id, account_id }. Re-derive hubspot_owner_id from the routing
// table so downstream is uniform. Routing table inlined -- same tradeoff as above.
const rt = {
  pools: {
    enterprise: [
      { rep_id: 'rep_ana', name: 'Ana Costa', hubspot_owner_id: '' },
      { rep_id: 'rep_bruno', name: 'Bruno Lima', hubspot_owner_id: '' },
    ],
    smb: [
      { rep_id: 'rep_carla', name: 'Carla Nunes', hubspot_owner_id: '' },
      { rep_id: 'rep_diego', name: 'Diego Souza', hubspot_owner_id: '' },
    ],
  },
  routing: [
    { match: { company_size_gte: 200 }, pool: 'enterprise' },
    { match: { company_size_gte: 0 }, pool: 'smb' },
  ],
};
const owner_id = $json.owner_id;
const account_id = $json.account_id;
let hubspot_owner_id = '';
for (const k of Object.keys(rt.pools || {})) {
  const found = (rt.pools[k] || []).find((r) => r.rep_id === owner_id);
  if (found) { hubspot_owner_id = found.hubspot_owner_id || ''; break; }
}
return { json: { owner_id, hubspot_owner_id, account_id } };

// Company Found? exists as a visible branch for the diagram; this node independently
// re-derives hubspot_company_id so BOTH branches converge on one write call below --
// keeps the write node's expressions stable no matter which branch fired.
const search = $json; // HubSpot Search Company By Domain output (post-IF passthrough)
const found = (Array.isArray(search.results) && search.results.length > 0) ? search.results[0] : null;
const ctx = $('Score Lead').item.json;
return { json: {
  hubspot_company_id: found ? found.id : null,
  domain: ctx.domain, company_name: ctx.company_name, company: ctx.company,
} };

// HubSpot company write: exponential backoff with jitter (500ms * 2^n + jitter, capped at 30s),
// honoring Retry-After when HubSpot sends it. Retries 429, any 5xx and network errors
// (no status). Any other 4xx will not fix itself, so it goes straight to Give Up.
// $runIndex counts this node's own runs for the item: 0 on the first failure. With
// attempt < 5 that is one call plus up to five retries.
const attempt = $runIndex;
const errItem = $json;
const errObj = errItem.error || errItem;
const rawCode = errObj.httpCode || errObj.statusCode || errObj.status
  || (errObj.cause && errObj.cause.statusCode)
  || ((String(errObj.message || '').match(/^(\d{3})\b/) || [])[1]);
const statusCode = Number(rawCode) || null;
const headers = errObj.headers || (errObj.response && errObj.response.headers) || {};
const retryAfterHeader = headers['retry-after'] || headers['Retry-After'];

const maxRetries = 5;
const isRetryable = statusCode === null || statusCode === 429 || (statusCode >= 500 && statusCode <= 599);
const shouldRetry = isRetryable && attempt < maxRetries;

let delayMs;
if (retryAfterHeader) {
  delayMs = Number(retryAfterHeader) * 1000;
} else {
  const base = 500 * Math.pow(2, attempt);
  const jitter = Math.floor(Math.random() * 250);
  delayMs = Math.min(30000, base + jitter);
}
const errorMessage = String(errObj.message || errObj.description || '').slice(0, 300);

return { json: { attempt, statusCode, errorMessage, shouldRetry, delayMsSeconds: Math.max(Math.ceil(delayMs / 1000), 1) } };

// Either the retries are spent (one call plus up to five retries) or HubSpot answered a
// 4xx other than 429. Record why, drop the company id and let the lead continue, so the
// alert still goes out. Update Lead HubSpot IDs writes the failure to the lead row.
const s = $json.statusCode;
const calls = ($json.attempt || 0) + 1;
const detail = (s ? 'HTTP ' + s : 'no response') + ' after ' + calls + ' call(s)'
  + ($json.errorMessage ? ': ' + $json.errorMessage : '');
return { json: { hubspot_company_id: null, hubspot_write_error: true, hubspot_write_error_detail: detail } };

// Convergence for the company leg. The success path carries the HubSpot company
// response ({id, ...}); the give-up path carries hubspot_write_error and its reason.
// Both are kept, so the failure reaches the lead row instead of being dropped here.
const raw = $json;
const failed = raw.hubspot_write_error === true;
const hubspot_company_id = failed ? null : (raw.id || raw.hubspot_company_id || null);
const existing = $('Prepare Company Write').item.json.hubspot_company_id;
const ctx = $('Score Lead').item.json;
return { json: {
  ...ctx,
  hubspot_company_id,
  company_action: failed ? 'failed' : (existing ? 'updated' : 'created'),
  hubspot_write_error: failed,
  hubspot_write_error_detail: failed ? 'company: ' + raw.hubspot_write_error_detail : null,
} };

// HubSpot contact write: exponential backoff with jitter (500ms * 2^n + jitter, capped at 30s),
// honoring Retry-After when HubSpot sends it. Retries 429, any 5xx and network errors
// (no status). Any other 4xx will not fix itself, so it goes straight to Give Up.
// $runIndex counts this node's own runs for the item: 0 on the first failure. With
// attempt < 5 that is one call plus up to five retries.
const attempt = $runIndex;
const errItem = $json;
const errObj = errItem.error || errItem;
const rawCode = errObj.httpCode || errObj.statusCode || errObj.status
  || (errObj.cause && errObj.cause.statusCode)
  || ((String(errObj.message || '').match(/^(\d{3})\b/) || [])[1]);
const statusCode = Number(rawCode) || null;
const headers = errObj.headers || (errObj.response && errObj.response.headers) || {};
const retryAfterHeader = headers['retry-after'] || headers['Retry-After'];

const maxRetries = 5;
const isRetryable = statusCode === null || statusCode === 429 || (statusCode >= 500 && statusCode <= 599);
const shouldRetry = isRetryable && attempt < maxRetries;

let delayMs;
if (retryAfterHeader) {
  delayMs = Number(retryAfterHeader) * 1000;
} else {
  const base = 500 * Math.pow(2, attempt);
  const jitter = Math.floor(Math.random() * 250);
  delayMs = Math.min(30000, base + jitter);
}
const errorMessage = String(errObj.message || errObj.description || '').slice(0, 300);

return { json: { attempt, statusCode, errorMessage, shouldRetry, delayMsSeconds: Math.max(Math.ceil(delayMs / 1000), 1) } };

// Either the retries are spent (one call plus up to five retries) or HubSpot answered a
// 4xx other than 429. Record why, drop the contact id and let the lead continue, so the
// alert still goes out. Update Lead HubSpot IDs writes the failure to the lead row.
const s = $json.statusCode;
const calls = ($json.attempt || 0) + 1;
const detail = (s ? 'HTTP ' + s : 'no response') + ' after ' + calls + ' call(s)'
  + ($json.errorMessage ? ': ' + $json.errorMessage : '');
return { json: { hubspot_contact_id: null, hubspot_write_error: true, hubspot_write_error_detail: detail } };

// Convergence for the contact leg. The success path carries the HubSpot contact
// response ({id, ...}); the give-up path carries hubspot_write_error and its reason.
// Failures from the company leg ride along, so Update Lead HubSpot IDs records both.
const raw = $json;
const ctx = $('Merge Company Result').item.json;
const existing = $('Prepare Contact Write').item.json.hubspot_contact_id;
const owner = $('Owner Resolved').item.json;
const contactFailed = raw.hubspot_write_error === true;
const hubspot_contact_id = contactFailed ? null : (raw.id || null);
const details = [ctx.hubspot_write_error_detail, contactFailed ? 'contact: ' + raw.hubspot_write_error_detail : null].filter(Boolean);
return { json: {
  ...ctx,
  hubspot_contact_id,
  contact_action: contactFailed ? 'failed' : (existing ? 'updated' : 'created'),
  hubspot_write_error: ctx.hubspot_write_error === true || contactFailed,
  hubspot_write_error_detail: details.length ? details.join('; ') : null,
  owner_id: owner.owner_id,
  account_id: owner.account_id,
} };

// Contact Found? is a visible branch; both branches land here so the write node below
// keeps one set of expressions. A contact found by email is PATCHed by id; a missing
// one is POSTed with its company association inline.
const search = $json; // HubSpot Search Contact By Email output (post-IF passthrough)
const found = (Array.isArray(search.results) && search.results.length > 0) ? search.results[0] : null;
return { json: { hubspot_contact_id: found ? found.id : null } };
